  ('TLS-CAP-019', 'Airport Cargo Terminal Receipt & System Update', 'Cargo terminal records, airport community system requests, load sheets, ramp coordination records; Load-control data and ramp cargo plan; ULD or cargo-unit exception; Cargo handoff and load-control record; Cargo terminal receipt record', 19),
  ('TLS-CAP-020', 'Ramp Cargo & Load-Control Handoff', 'Ramp timing, cargo manifest and flight/load-control cutoff; ULD/cargo unit, AWB and terminal location record; Load-control data and cargo manifest; ULD mismatch, cutoff miss or ramp exception evidence; Ramp cargo handoff confirmation', 20),
  ('TLS-CAP-021', 'Ambient Warehouse Receiving & Putaway Control', 'ASN, SKU list and pallet receipt; Pallet condition and discrepancy evidence; SKU/bin availability and putaway list; Putaway scan and inventory record; Putaway and inventory receipt record', 21),
