  ('TLS-CAP-025', 'CEP Hub Sortation & Linehaul Dispatch Control', 'Parcel scans and hub intake batch; Parcel destination, service level and route bag plan; Bag manifest and linehaul route plan; Linehaul capacity and sortation exception evidence; Sortation and linehaul dispatch record', 25),
  ('TLS-CAP-026', 'Parcel Exception Rework & Hub Control', 'Exception code, waybill, parcel image and remarks; Parcel exception evidence; Parcel and exception category; Waybill and customer SLA; Parcel exception resolution record', 26),
