  ('MBE-CAP01', 'Port Call and Berth Execution', 'Review vessel-call readiness, berth windows, ETA changes, yard density and crane allocation evidence; identify operational conflicts and prepare controlled berth-planning handoffs without overriding port or terminal authority.', 1),
  ('MBE-CAP02', 'Terminal Safety, Cargo and Gate Control', 'Check gate passes, cargo manifests, permit files, hazardous-cargo indicators and HSE records; identify safety or documentation exceptions and escalate them without issuing formal clearance.', 2),
  ('MBE-CAP03', 'Shipping Documentation and Voyage File Control', 'Verify bills of lading, manifests, voyage orders, consignee and shipper details, sailing schedules and cut-off records; document mismatches and prepare carrier or customer handoffs.', 3),
  ('MBE-CAP04', 'Voyage and Inland Waterway Coordination', 'Track vessel readiness, route schedules, terminal handoffs, inland-waterway restrictions and delay risks; prepare operator-facing readiness and escalation records without making navigation decisions.', 4),
  ('MBE-CAP05', 'Yard Planning and Design Support', 'Review drawing registers, revision status, hull-block plans, production work packs and material take-offs; identify design-document or work-pack gaps while preserving class and design approval boundaries.', 5),
  ('MBE-CAP06', 'Shipyard QA, Repair, HSE and Recycling Support', 'Review NDT logs, permits to work, repair-closure files, IHM checklists and hazard-control records; identify missing QA, HSE or recycling evidence without certifying technical acceptance.', 6),
  ('MBE-CAP07', 'Fisheries Landing and Catch Documentation', 'Reconcile catch logs, landing sheets, species records, quantities and fisher or vessel identifiers; document discrepancies and prepare harbour or extension-support handoffs.', 7),
  ('MBE-CAP08', 'Aquaculture Batch and Water-Quality Monitoring', 'Monitor pond, cage and hatchery batches, water-quality readings, feed or medicine records and health-risk indicators; document deviations and escalate technical concerns without diagnosing or approving treatment.', 8),
  ('MBE-CAP09', 'Seafood QA, Cold Chain and Export Support', 'Check cold-chain temperatures, batch traceability, QA holds and release documentation; record breaches and prepare quality or export handoffs without issuing final product approval.', 9),
  ('MBE-CAP10', 'Cruise Terminal Passenger Service Support', 'Check passenger manifests, boarding and baggage records, terminal-readiness evidence and incident information; manage service exceptions and escalate security or safety issues.', 10),
  ('MBE-CAP11', 'Coastal Experience and Marine Tourism Coordination', 'Coordinate shore-excursion plans, guide rosters, local marine assets, visitor issues and safety handoffs; support itinerary readiness without approving safety-critical activities.', 11),
  ('MBE-CAP12', 'Offshore Wind Survey Evidence Support', 'Review metocean data, LiDAR records, GIS layers, geophysical or geotechnical survey evidence and QC logs; identify evidence gaps within a future-facing offshore-wind benchmark pathway.', 12),
  ('MBE-CAP13', 'Offshore Project Interface and Grid Evidence Support', 'Organise lease, permit, contractor-readiness, risk-register and grid-interface evidence; identify unresolved dependencies without approving permits, construction or grid connection.', 13),
  ('MBE-CAP14', 'Marine Sample Chain and Lab QA', 'Maintain sample identifiers, chain-of-custody records, assay sheets, LIMS entries and laboratory-deviation evidence; identify traceability or QA failures without approving scientific or regulatory claims.', 14),
  ('MBE-CAP15', 'Biodiversity and Taxonomy Data Support', 'Curate species-identification records, taxonomy datasets, biodiversity observations and GIS-linked references; identify duplicate, incomplete or uncertain records and escalate them for expert review.', 15),
  ('MBE-CAP16', 'Coastal Compliance Evidence Preparation', 'Prepare CRZ, EIA, pollution-monitoring, sampling and baseline-map evidence matrices; identify missing or inconsistent compliance evidence without making regulatory decisions.', 16),
  ('MBE-CAP17', 'Marine Data and Coastal Resilience Support', 'Prepare habitat maps, vulnerability layers, GIS datasets, resilience dashboards and public-reporting evidence; perform data-quality checks without issuing official disaster-risk or resilience certification.', 17),
